import type { Group } from "./in-questions";
const GUIDE = "Indiana Secretary of State, Notary Public Guide, revised May 20, 2024; https://inbiz.in.gov/Assets/NotaryGuide.pdf";
const LAW = "Indiana Code Article 33-42; https://iga.in.gov/laws/2026/ic/titles/33#33-42";
const SOS = "Indiana Secretary of State, 2025 Recorders Conference presentation; https://www.in.gov/sboa/files/Grosser_SOS-Business-Services-Division_Notary.pdf";
export const inAdditionalGroups: Group[] = [
{card:13,study:"identification",topic:"identification",source:GUIDE+"; Duties; "+LAW+"; IC 33-42-9-3",items:[
["For an ordinary in-person acknowledgment, who must appear before the notary?","The person acknowledging the signature","Personal appearance of the principal allows the notary to identify that individual and receive the acknowledgment.",["Only a courier delivering the record","A courier cannot supply the absent principal's personal appearance."],["Only the customer's employer","An employer does not replace the signer."],["Nobody if the signature looks familiar","Signature recognition alone is not personal appearance."]],
["A courier brings a signed affidavit while the affiant remains at home. Can the notary perform an ordinary jurat?","No; the affiant must personally appear for the required act","A courier's delivery does not allow the notary to administer the affiant's oath or observe the required execution.",["Yes; the courier may take the affiant's oath","The courier cannot swear for the absent affiant."],["Yes; a photograph of the affiant is enough","A photograph is not personal appearance."],["Yes; notarizing after business hours waives appearance","The time of day does not waive the requirement."]],
["Does knowing a signer personally remove the appearance requirement for an ordinary signature notarization?","No, the signer must still appear","Identity and personal appearance are separate requirements; knowing the signer does not permit notarizing an absent signer.",["Yes; friends never need to appear","Friendship does not waive appearance."],["Yes; if the notary keeps the document overnight","Possession of the record does not bring the signer before the notary."],["Yes; if no fee is charged","A free act still requires the principal's appearance."]],
["A customer asks an ordinary notary to replace the meeting with a phone call. What is the sound response?","Require proper personal appearance for the ordinary act","An ordinary telephone call is not the physical personal appearance required for an in-person notarization.",["Accept any voice the customer recognizes","Another person's recognition does not establish the required appearance."],["Use the customer's voicemail as an oath","A stored message is not administering the required act before the notary."],["Stamp first and meet the signer later","A later meeting does not cure an unperformed act at certification."]],
]},
{card:14,study:"identification",topic:"identification",source:GUIDE+"; Identification: Personal Knowledge",items:[
["What makes personal knowledge an acceptable identification method?","Certain knowledge from sufficient familiarity","The guide describes a substantial relationship and knowledge that leaves no reasonable doubt about identity.",["The signer shares the notary's first name","A shared name does not establish identity."],["The signer appears professionally dressed","Appearance is not personal knowledge."],["The signer introduces themself confidently","A self-introduction is not sufficient prior familiarity."]],
["A supervisor introduces a stranger to the notary that morning. May the notary call the stranger personally known solely on that introduction?","No, an introduction is insufficient","The guide specifically warns against treating a new introduction by an employer as the necessary personal familiarity.",["Yes; a supervisor's title establishes identity","Employment authority does not establish personal knowledge."],["Yes; a handshake is conclusive","A handshake is not sufficient familiarity."],["Yes; if the stranger knows the supervisor","The notary must use an authorized identification method."]],
["A notary recognizes a customer from years of substantial dealings and has no reasonable identity doubt. Which method may apply?","Personal knowledge","Prior dealings and sufficient familiarity can establish the personal-knowledge method described in the guide.",["Automatic copy certification","Copy certification addresses a copy, not the individual's identity."],["An employer exception","No employer exception is needed for personal knowledge."],["A waiver of every other notarial duty","Identity does not waive appearance, willingness, or certificate duties."]],
["The notary vaguely recognizes a face but cannot remember the person's name. What is appropriate?","Obtain satisfactory identity evidence","A vague acquaintance does not satisfy the guide's certainty standard; reliable identity evidence is needed.",["Guess the name from the document","Guessing is not identifying the signer."],["Ask the signer to choose a name for the certificate","The certificate must identify the actual principal."],["Use personal knowledge because any recognition suffices","The guide calls for more than a nodding acquaintance."]],
]},
{card:15,study:"identification",topic:"identification",source:GUIDE+"; Identification; "+LAW+"; IC 33-42-9-4",items:[
["Which credential is among the identification types listed in the Indiana guide?","A state-issued driver's license","The guide lists state driver's licenses and identity cards, passports, military ID, tribal ID, and qualifying government photo documents.",["A grocery loyalty card","A store loyalty card is not one of the listed government credentials."],["A handwritten name tag","A self-created name tag is not government identification."],["A business appointment card","An appointment card does not establish the claimed identity."]],
["The guide allows listed identification credentials that are current or expired for no more than what period?","Three years","The guide's identification section uses a current-or-not-more-than-three-years-expired standard for the listed credentials.",["Three days","The guide does not use a three-day expiration limit."],["Ten years","Ten years exceeds the guide's stated period."],["Any period if the photo is clear","A clear photograph does not erase the expiration limit."]],
["A signer offers only a gym membership card. What is the appropriate next step?","Seek acceptable identity evidence","A private gym card does not become a listed government identification credential merely because it includes a name.",["Accept the gym card because it has a photograph","A private membership card does not become a listed government credential by carrying a photograph."],["Accept the gym card with the signer's verbal assurance","A verbal assurance does not transform a private card into the listed credential."],["Treat frequent gym attendance as personal knowledge","The notary needs sufficient personal familiarity, rather than the signer's attendance claim."]],
["Is an officially recognized foreign passport automatically excluded solely because it is not a U.S. passport?","No, a recognized foreign passport may qualify","The guide lists a U.S. passport or an officially recognized passport of a foreign country, subject to the applicable standards.",["Yes; every foreign credential is forbidden","That contradicts the guide's passport listing."],["No; every foreign document is acceptable ID","Accepting a recognized passport does not mean every foreign document qualifies."],["Yes; only an Indiana driver's license can be used","The guide recognizes several credential types and issuing jurisdictions."]],
]},
{card:16,study:"identification",topic:"identification",source:GUIDE+"; Identification: Credible Witness",items:[
["What must a credible identifying witness know?","The signer personally","The witness must personally know the signer and attest to that identity under oath or affirmation.",["Only the record's page count","Page count does not establish personal knowledge of the signer."],["Only the notary's employer","Knowing the employer does not establish the signer's identity."],["Only the fee schedule","Fee knowledge has no identifying effect."]],
["How may the notary establish the credible witness's identity under the guide?","Personal knowledge or a listed credential","The guide allows personal knowledge or the specified identification documents for the witness, who must personally know the signer.",["Accept an unidentified witness's claim","The witness must also be identified."],["Use the signer's guess about the witness","A guess does not identify the witness."],["Skip identification if the witness is paid","Payment does not eliminate identity requirements."]],
["A stranger offers to identify another stranger by reading the name on the record. Is that a credible-witness basis?","No, the witness must personally know the signer","A credible identifying witness must personally know the signer; reading a supplied name is not that knowledge.",["Yes; reading is enough","Reading the record does not create personal familiarity."],["Yes; if the witness speaks clearly","Clear speech does not substitute for personal knowledge."],["Yes; if two strangers make the same guess","Repeating an unsupported claim does not establish the required knowledge."]],
["What distinguishes a credible identifying witness from a person who merely accompanies the signer?","A qualified witness gives sworn identity evidence","Being present as a companion does not itself make someone a qualified credible witness.",["The companion reports only that the signature looks familiar","Signature familiarity alone does not supply the qualified witness's sworn identity evidence."],["The companion promises to confirm identity after the meeting","The identity evidence must be established for the actual act."],["The companion signs the record but gives no identity testimony","Merely signing a record does not establish the credible identifying witness's required testimony."]],
]},
{card:17,study:"identification",topic:"identification",source:GUIDE+"; Identification; "+LAW+"; IC 33-42-9-4(c)",items:[
["A listed credential is presented, but the notary still reasonably doubts identity. What may the notary request?","Additional identification or information","Indiana permits additional identification or information when necessary to establish the individual's identity.",["No further evidence under any circumstances","A credential does not forbid reasonable additional inquiry."],["A blank certificate signed by the customer","A blank certificate is not identity evidence."],["A tip to overlook the doubt","Payment cannot substitute for identification."]],
["The photograph on a credential does not appear to match the person presenting it. What should the notary do?","Resolve the identity discrepancy before performing the act","The notary must identify the actual person; possession of an otherwise listed card does not settle an unresolved mismatch.",["Ignore the photo because the name matches","Both the person and the claimed identity require evaluation."],["Notarize now and compare later","Identity must be established before certifying the act."],["Ask the customer to alter the photograph","Altering a credential is not a proper identification solution."]],
["A customer says asking for more identification is impossible once any card is shown. Is that correct?","No; the notary may require additional identity information","The statute preserves the notarial officer's ability to seek additional information or credentials.",["Yes; a card ends all inquiry","The additional-information authority contradicts that claim."],["Yes; customer demand controls identity findings","The notary makes the required identity determination."],["Yes; unless the notary increases the fee","The authority to seek evidence is not purchased through fees."]],
["A notarization is urgently needed, but the notary cannot establish the signer's identity. What is appropriate?","Do not complete the act until identity requirements are satisfied","Urgency does not excuse the notary's required identity determination.",["Use the deadline as identity evidence","A deadline does not identify a person."],["Have the signer promise to bring ID next month","A future promise does not establish identity now."],["Stamp the ID instead of the record","Changing the item stamped does not resolve the identity problem."]],
]},
{card:18,study:"notarial-acts",topic:"acknowledgments",source:GUIDE+"; Acknowledgment; "+SOS+"; Forms of Notarial Acts",items:[
["What does a signer communicate in an acknowledgment?","Authentic and voluntary execution","An acknowledgment concerns the signer's acknowledged execution, rather than a sworn declaration that every statement is true.",["That the notary wrote the entire document","The notary need not be the document's author."],["That the notary guarantees the transaction's legality","An acknowledgment does not provide a legal guarantee."],["That no identification was needed","The signer still must be properly identified."]],
["A deed was signed yesterday. Today the identified signer appears and acknowledges it voluntarily. Must it be rejected solely because of yesterday's signature?","No, prior signatures may be acknowledged","For an acknowledgment, the signer appears and acknowledges execution; the signature need not always be placed in front of the notary.",["Yes; acknowledgments always require a new signature","That confuses an acknowledgment with signature witnessing."],["Yes; the certificate must instead be dated yesterday","The certificate records today's actual notarial act."],["No; appearance is therefore unnecessary","A prior signature does not waive today's personal appearance."]],
["Does taking an acknowledgment establish that the notary verified every factual statement in the record?","No, it concerns the acknowledged execution","The notary identifies the signer and receives the acknowledgment without guaranteeing all underlying factual or legal assertions.",["Yes; the seal guarantees all facts","A seal does not turn the notary into a guarantor of the document."],["Yes; any false term becomes true when stamped","Notarization cannot make a false statement true."],["No; the notary may disregard identification","The absence of a content guarantee does not eliminate identity duties."]],
["A certificate says acknowledged before me, but no acknowledgment was received. What is wrong?","It certifies an unperformed act","Certificate wording must describe the actual act, including the required acknowledgment by the principal.",["Nothing; a stamp replaces the acknowledgment","The seal cannot replace the required act."],["Only the ink color matters","The missing act is substantive, not an ink issue."],["An acknowledgment is identical to silent document delivery","Delivery alone is not receiving the signer's acknowledgment."]],
]},
{card:19,study:"notarial-acts",topic:"acknowledgments",source:GUIDE+"; Representative Acknowledgment",items:[
["An individual acknowledges a record signed for a company. Which capacity should an appropriate certificate reflect?","The representative's stated capacity","A representative acknowledgment identifies the human actor and the capacity in which the record was executed.",["Only the company's street address","An address does not describe the actor's representative capacity."],["The notary as the company's president","The notary must not substitute themself for the representative."],["The company's seal manufacturer","A vendor is unrelated to the representative act."]],
["Who must personally appear when a company officer's execution is acknowledged?","The individual acting for the company","An organization acts through an individual; the notary identifies and receives the acknowledgment from that appearing person.",["The corporation as an abstract entity","An entity cannot physically appear without an individual actor."],["Any unrelated courier","A courier does not automatically become the executing representative."],["The notary's supervisor only","The supervisor is not a substitute for the principal."]],
["A customer wants the notary to invent a representative title because the record is unclear. What should the notary do?","Require clarification rather than fabricate a capacity","The notarial certificate must accurately reflect the actual acknowledgment and capacity, not an invented office.",["Choose the highest corporate title","A guessed title may falsely describe the act."],["Use owner for every representative","Different representative capacities are not interchangeable."],["Leave the principal unidentified","Omitting the actor does not resolve the capacity question."]],
["How does an individual acknowledgment differ from a representative acknowledgment?","The latter reflects execution in a stated representative capacity","Both require the appearing individual's identity and acknowledgment; representative wording additionally reflects the role in which that person acts.",["Only representative signers need identification","Identity is required for both."],["A representative never appears personally","The acting individual still appears."],["An individual acknowledgment always requires an oath about contents","An acknowledgment is distinct from verification on oath."]],
]},
{card:20,study:"notarial-acts",topic:"jurats",source:GUIDE+"; Oaths and Affirmations",items:[
["What alternative is available to a person who does not wish to take a religious oath?","A solemn affirmation","An affirmation is the nonreligious alternative for a person undertaking the same duty to tell the truth.",["A promise with no duty of truthfulness","An affirmation carries the truthfulness obligation."],["A stamp with no verbal act","The notary must actually administer the oath or affirmation."],["An acknowledgment substituted without instruction","An acknowledgment is a different notarial act."]],
["Must the notary actually administer an oath or affirmation for a verification requiring one?","Yes, administer the oath or affirmation","A completed jurat certifies a sworn or affirmed act that must actually occur before the notary.",["No; the seal automatically administers it","A seal is not administration of an oath."],["No; a printed title of Affidavit is enough","A document heading does not administer a verbal undertaking."],["No; the customer can swear next week","A later oath cannot be certified as already administered."]],
["Which statement best compares an oath and an affirmation?","Both require a truthful undertaking","The distinction concerns the form of undertaking, not whether the person is obligated to tell the truth.",["Only an oath concerns truthfulness","An affirmation also obligates truthful statements."],["An affirmation is merely optional small talk","It is a solemn notarial undertaking."],["An oath makes the notary the author of the statement","The signer remains responsible for the statement."]],
["A signer says I affirm that the statement is true during the administered act. Should the notary reject it solely for avoiding religious words?","No; an affirmation is an accepted alternative","The signer may affirm rather than swear; the notary should use accurate certificate wording reflecting the act performed.",["Yes; every signer must use religious language","An affirmation does not require that language."],["Yes; only attorneys may affirm","An affirmation is not restricted to attorneys."],["No; therefore identity is unnecessary","The permitted affirmation does not waive identification."]],
]},
{card:21,study:"notarial-acts",topic:"jurats",source:GUIDE+"; Verification on Oath or Affirmation; "+SOS+"; Jurat",items:[
["What combination characterizes a verification on oath or affirmation?","A sworn or affirmed signing before the notary","The SOS presentation distinguishes a jurat by the oath or affirmation and execution in the notary's presence.",["Only a notary seal on unsigned paper","An unsigned blank with a seal is not a verification."],["A courier's acknowledgment of someone else's statement","The affiant must perform the required act."],["A notary's promise that the transaction will succeed","A jurat does not guarantee the transaction's outcome."]],
["An affiant signed a statement at home and asks for a jurat without signing before the notary. What must be addressed?","Signing before the notary and taking the oath","A jurat involves the affiant's sworn or affirmed execution before the notary; it is not merely acknowledgment of an old signature.",["Only the number of staple holes","Physical attachment is not the missing execution requirement."],["Only the customer's preferred fee","Payment does not replace the act."],["Nothing; every previous signature satisfies a jurat","A previously signed record does not by itself supply execution before the notary."]],
["Does a jurat mean the notary personally knows every statement in the affidavit to be true?","No, the affiant makes the sworn statement","The notary administers and certifies the affiant's act rather than guaranteeing personal knowledge of every asserted fact.",["Yes; the notary becomes the fact witness for all contents","That overstates the notary's certification."],["Yes; a seal cures known falsehoods","Notarization does not cure a false statement."],["No; an oath is therefore unnecessary","The affiant's oath or affirmation is essential."]],
["Which certificate language indicates a verification rather than a simple acknowledgment?","Signed and sworn to or affirmed before me","Sworn-or-affirmed wording reflects a verification; acknowledged wording alone describes a different act.",["Received by ordinary mail","Mail receipt does not certify a sworn act."],["Copy compared to original","That language concerns copy certification."],["Acknowledged before me only","That is acknowledgment language and omits the verification's oath."]],
]},
{card:22,study:"notarial-acts",topic:"acknowledgments",source:SOS+"; Witnessing a Signature; "+GUIDE+"; Notarial Acts",items:[
["What is central to the notarial act of witnessing a signature?","The principal signs before the notary","Signature witnessing requires observing the principal's execution and is distinct from acknowledging a previously placed signature.",["The notary signs for every customer","The principal normally signs; substitute execution has separate conditions."],["The document arrives already signed by mail","Mailed delivery does not allow witnessing execution."],["A retailer recognizes the paper brand","Paper recognition has no notarial significance."]],
["Does signature witnessing automatically include a sworn declaration about the record's truth?","No, witnessing alone supplies no oath","Witnessing execution and administering a sworn verification have different requirements and should not be conflated.",["Yes; every witnessed signature is an affidavit","Witnessing alone does not administer an oath."],["Yes; a seal is always an oath","A seal does not itself administer an oath."],["No; signature witnessing therefore requires no identity check","The signer must still be identified."]],
["The requested act is signature witnessing, but the signer is absent. Can another person merely confirm that the signature looks right?","No; that does not let the notary witness the execution","An unsupported confirmation of appearance is not observing the required signer execute the record.",["Yes; any familiar-looking signature qualifies","Signature appearance is not witnessing execution."],["Yes; if the witness brings a business card","A business card does not replace the principal's act."],["Yes; if the notary dates the certificate yesterday","Backdating does not cure the missing act."]],
["Why should a notary distinguish acknowledgment from signature witnessing before completing a certificate?","Witnessing requires observing the signature","Selecting the correct act determines what must actually happen before the notary and what the certificate can truthfully state.",["Only an acknowledgment requires the signer to be identified","Both acts require appropriate identification of the principal."],["Only signature witnessing requires the signer to appear","The signer must also appear to acknowledge the signature."],["Acknowledgment always adds a sworn statement about the contents","An acknowledgment does not itself administer a truth-verification oath."]],
]},
{card:23,study:"notarial-acts",topic:"copy-certification",source:GUIDE+"; Certified Copies and True Copies; "+SOS+"; Forms of Notarial Acts",items:[
["What does a notary determine when certifying a copy?","A full and accurate reproduction","Copy certification concerns correspondence between the copy and the source record, rather than a guarantee of every underlying assertion.",["That every statement in the original is true","Comparing copies does not establish all substantive facts."],["That the owner has no debts","Debt status is unrelated to the copy comparison."],["That the original can be destroyed safely","A copy certification does not authorize destruction."]],
["A customer brings a photocopy but no source record for comparison. What essential step is missing?","Comparison with the source record","A proper copy certification requires determining that the copy accurately reproduces the relevant source record.",["The customer's assurance that the copy is accurate","Customer assurance does not let the notary compare the copy with its source."],["The notary's signature on the unexamined copy","Signing does not establish that an unexamined copy matches its source."],["The customer's request for an acknowledgment instead","Changing the requested act would not perform the missing copy comparison."]],
["A person needs an official certified birth record. Where should the person obtain that official record?","The authorized vital-records custodian","An official custodian's certified vital record should be obtained through the responsible office rather than represented as issued by a notary.",["From a notary who invents a registrar's certification","A notary cannot impersonate the records custodian."],["From any person with a photocopier","A photocopier does not confer official custodian authority."],["From a stamp retailer","A stamp retailer cannot issue government vital records."]],
["Is notarizing a person's sworn statement about an attached copy the same as the notary directly certifying the copy's accuracy?","No; the certificate must describe the actual act performed","A verification of the person's statement certifies that person's sworn act; a direct copy certification involves the notary's own comparison.",["Yes; the two certificates always mean exactly the same thing","They certify different acts and assertions."],["Yes; any attachment makes the notary a registrar","Attaching a copy does not grant custodian authority."],["No; therefore neither act ever needs a certificate","Every notarial act still requires appropriate certification."]],
]},
{card:24,study:"notarial-acts",topic:"acknowledgments",source:GUIDE+"; Special Circumstances; "+LAW+"; IC 33-42-9-6",items:[
["When can the statutory designated-signer procedure be relevant?","When the principal is physically unable to sign the record","Indiana provides a procedure for a physically unable principal to direct another individual to affix the principal's signature.",["Whenever the principal is busy","Convenience alone is not the stated physical-inability condition."],["Whenever the notary prefers a different handwriting style","The notary's preference is irrelevant."],["Whenever a courier has the paper","Possession does not establish the principal's direction."]],
["What is essential to a designated signer acting for a physically unable principal?","The principal directs the signature","The procedure depends on the principal's own direction and intent, rather than another person's unilateral decision.",["The designee acts without telling the principal","Unilateral action lacks the required direction."],["The employer approves instead of the principal","The employer cannot replace the principal's intent."],["The notary assumes silence is a direction","Silence is not adequate evidence of the required direction."]],
["How should the record reflect a signature affixed under Indiana's physical-inability procedure?","Identify the designee and principal and convey that the signing was at the principal's direction","The statutory procedure calls for an indication of the designee's signature, the principal's name, and the principal's intent.",["Conceal that another person signed","Concealment would misdescribe the execution."],["List only the notary's employer","The relevant actors are the principal and designee."],["Pretend the principal personally wrote the signature","The record should truthfully reflect substitute execution."]],
["A principal cannot hold a pen but can communicate a clear signing direction. Does physical inability alone mean the principal lacks intent?","No; physical inability and knowing direction are separate questions","The designated-signer procedure accommodates physical inability while preserving the principal's direction and the other notarial safeguards.",["Yes; any motor impairment eliminates legal intent","Physical impairment does not automatically establish inability to direct an act."],["Yes; a notary may simply invent the principal's wishes","The principal's actual direction remains essential."],["No; therefore identification is unnecessary","Accommodation does not remove identity requirements."]],
]},
{card:25,study:"notarial-acts",topic:"commission",source:SOS+"; Notarial Jurisdiction",items:[
["Where may an Indiana notary physically perform acts under an Indiana commission?","Within Indiana's geographic boundaries","The Secretary of State states that Indiana notaries may not notarize while physically outside Indiana.",["Anywhere in the United States","An Indiana commission does not grant nationwide physical jurisdiction."],["Only in the notary's home street","The commission is not limited to a single street."],["Anywhere the customer resides","The customer's residence does not determine the notary's jurisdiction."]],
["An Indiana notary is visiting Illinois and is asked to use the Indiana commission there. What is the proper response?","Do not perform the act there under the Indiana commission","The notary must be within Indiana when exercising Indiana notarial authority.",["Proceed if the document concerns Indiana property","Property location does not relocate the notary."],["Proceed if the customer lives in Indiana","The customer's residence does not expand geographic authority."],["Proceed only without charging","A fee waiver does not extend jurisdiction."]],
["Is an Indiana notary limited to notarizing in the county of residence or employment?","No; Indiana authority extends throughout the state","The venue records where the act occurs; the notary's home or employment county does not confine statewide authority.",["Yes; every other county needs a new commission","The Indiana commission permits statewide acts."],["Yes; unless the signer owns a statewide business","The signer's business is unrelated to the geographic scope."],["No; therefore acts in neighboring states are allowed","Statewide authority does not mean interstate authority."]],
["A California resident appears before an Indiana notary in Indiana with a record for use elsewhere. Does the signer's residence alone bar the act?","No; the notary's location and all act requirements control","The Indiana commission's geographic restriction concerns where the notary acts, not a requirement that every signer live in Indiana.",["Yes; every signer must be an Indiana resident","The geographic rule does not impose that signer-residence requirement."],["No; the notary may also travel to California and use the same commission","The notary must remain within Indiana's jurisdiction."],["Yes; only Indiana-drafted paper can be notarized","Document origin is not the jurisdiction test."]],
]},
{card:26,study:"certificates",topic:"acknowledgments",source:SOS+"; Notarial Certificates; "+GUIDE+"; Certificate Completion",items:[
["A customer requests an acknowledgment on a deed that has signatures and a stamp box but no notarial wording. What is missing?","An acknowledgment certificate","A stamp box does not describe a notarial act. The requested acknowledgment needs an appropriate completed certificate.",["A copy of the notary's surety bond","The bond does not supply the certificate for the deed's acknowledgment."],["An affidavit replacing the signed deed","Replacing the transaction record with an affidavit does not supply its requested acknowledgment."],["An apostille issued before the meeting","An apostille is a separate authentication and does not perform the acknowledgment."]],
["A notary whose commission lists Allen County takes an acknowledgment in Marion County. Which county identifies the location of this act?","Marion County, where the act occurred","The certificate distinguishes the county where the act occurs from the notary's county of commission. Here the act occurs in Marion County.",["Allen County, listed on the commission","The commission county does not change where this particular act occurred."],["The county where the signer lives","The signer's residence does not establish the location of the act."],["The county where the deed will be recorded","The later recording location does not establish where the acknowledgment occurred."]],
["A signer acknowledges an existing signature without taking an oath. The certificate says the signer swore to the record's truth. What is the defect?","The certificate describes an unperformed oath","A certificate must describe the act actually performed. An acknowledgment without an oath cannot be certified as a sworn verification.",["The signature should have been dated by the notary","Changing the signature date does not supply the missing oath."],["The seal must replace the sworn certificate wording","A seal cannot substitute for accurate wording that describes the actual act."],["The signer should certify the notary's signature","The principal does not certify the notary's official signature to cure an incorrect act description."]],
["Mira and Leon signed a record, but only Mira appears before the notary. A preprinted certificate says both appeared. What can it truthfully state?","That Mira personally appeared","The certificate must identify the actual appearing principal. Leon's existing signature does not establish that he appeared before this notary.",["That both appeared because both signatures are present","Two signatures on the record do not establish personal appearance by both signers."],["That Leon appeared if Mira confirms his signature","Mira's confirmation cannot supply Leon's personal appearance."],["That neither appeared because one signer is absent","Mira did appear. The certificate should accurately reflect her act without falsely including Leon."]],
]},
{card:27,study:"certificates",topic:"acknowledgments",source:GUIDE+"; Undated, Post-dated and Antedated Certificates",items:[
["Which date belongs in the notarial certificate for an act performed today?","Today's actual notarial-act date","The certificate must truthfully state when the notarial act occurred, rather than an earlier signing or requested transaction date.",["The date the customer first drafted the record","Drafting and the notarial act are different events."],["The customer's preferred future date","Future dating misstates the time of the act."],["The date the notary ordered the seal","Seal ordering is unrelated to the act's date."]],
["A customer wants yesterday's date so a filing looks timely. What should the notary do?","Refuse to backdate the notarial certificate","The guide warns against antedating; the certificate must reflect the actual act date.",["Use yesterday if the customer requests it in writing","Written consent does not make a false date accurate."],["Leave the date for the customer to complete later","The notary must complete an accurate certificate."],["Charge extra for the earlier date","Payment cannot authorize false dating."]],
["An acknowledgment is taken on November 13 for a record signed November 10. Which date describes the acknowledgment?","November 13","A preexisting signature may be acknowledged later; the certificate records when the acknowledgment was actually taken.",["November 10 because that is the signing date","The signing date is not necessarily the notarial-act date."],["November 14 to allow mailing time","Mailing does not justify postdating the act."],["Either date at the customer's option","The actual act date is not optional."]],
["May a notary complete a certificate today dated next Monday because delivery occurs then?","No, use the actual act date","The notarial certificate must reflect the act's actual date, not a future delivery or transaction date.",["Yes; postal delivery controls the notarial date","The date of mailing or receipt is not the act's date."],["Yes; a future date is always safer","A deliberately inaccurate future date is not proper."],["Yes; if the signer agrees","Agreement does not permit false certification."]],
]},
{card:28,study:"certificates",topic:"acknowledgments",source:SOS+"; Notary Signatures; "+GUIDE+"; Certificates",items:[
["Who signs the notarial certificate as notary public?","The commissioned notary who performed the act","A notarial certificate is the performing notary's official signed statement; another person cannot sign for convenience.",["Any receptionist with access to the file","Access to the file does not confer the notary's authority."],["The signer on behalf of the notary","The principal does not sign the notary's official certification."],["The employer who paid for the commission","Payment does not make the employer the performing officer."]],
["A notary's assistant offers to sign the certificate in the notary's name. Is that proper?","No; the notary's official signature is personal","The assistant cannot exercise the commission by imitating the notary's signature.",["Yes; if the assistant watched the meeting","Observation does not transfer the commission."],["Yes; whenever the office is busy","Workload does not authorize another person to sign as the notary."],["Yes; if the employer approves","Employer permission does not delegate public office."]],
["What signature standard does the SOS presentation give for certificates?","Match the signature sample on file","The notary submitted a handwritten application sample and is instructed to sign notarizations consistently with it.",["Use the customer's preferred handwriting","The official signature belongs to the notary."],["Use only the company's logo","A logo is not the required official handwritten signature."],["Make each signature intentionally different","Intentional variation conflicts with the consistency instruction."]],
["Is a perfectly legible seal enough when the notarial certificate lacks the notary's signature?","No; the certificate must be signed as well as properly sealed","The certificate is the notary's signed official statement; a seal does not replace the performing officer's signature.",["Yes; a seal always replaces a signature","Signature and seal serve separate completion requirements."],["Yes; if the signer initials the stamp","The principal's initials are not the notary's signature."],["Yes; if the fee is below ten dollars","The fee does not remove certificate requirements."]],
]},
{card:29,study:"certificates",topic:"acknowledgments",source:SOS+"; Certificate Attachment; "+GUIDE+"; Loose Certificates",items:[
["If the certificate is not printed in the record, how should it be associated with the record?","Securely affixed to the record","The SOS presentation requires the certificate to be in the document or securely affixed to it.",["Left on a different desk","A separated certificate can be detached from the act it describes."],["Given to any future customer","It evidences this act, not an unknown future record."],["Stored only in the notary's wallet","Private storage does not attach the certificate to the record."]],
["Why is an unattached completed certificate risky?","It could be attached to the wrong record","The guide's loose-certificate warning supports secure attachment so the certification remains connected to the actual document.",["It automatically increases the statutory fee","Attachment does not determine a new fee category."],["It makes every statement in any record true","No certificate has that effect."],["It grants the recipient a commission","A certificate does not commission its holder."]],
["A customer requests a completed certificate to attach to an unknown document next week. What should the notary do?","Decline the future-record certificate","The certificate must evidence an actual completed act and remain associated with its record.",["Provide several extras for convenience","Extras could be misused on records never involved in an act."],["Stamp the certificate without a date","Omitting the date does not make an incomplete certificate proper."],["Let the customer choose any record later","The customer cannot transfer this certification to a different act."]],
["An appropriate certificate must be added to a record with no notarial wording. What remains necessary?","Perform the act and attach its certificate","Adding certificate paper does not replace identification or the actual act; the completed certificate must remain connected to the record.",["Only attaching a blank sheet","Blank paper does not evidence a performed act."],["Only paying for stationery","Buying paper does not perform a notarization."],["Choosing legal consequences for the client","The notary should not provide unauthorized legal advice."]],
]},
{card:30,study:"certificates",topic:"prohibited-acts",source:GUIDE+"; Duties and Loose Certificates",items:[
["May a notary sign and seal blank certificates for use while the notary is away?","No; a certificate must correspond to an act actually performed","Presigned blank certificates allow others to create false evidence of acts the notary did not perform.",["Yes; if the employer locks them in a drawer","Storage does not make presigned future certifications proper."],["Yes; if each customer pays in advance","Prepayment does not authorize an unperformed act."],["Yes; if the notary returns within a week","A later return does not validate fabricated acts."]],
["A supervisor asks for ten sealed blank pages to speed up later closings. What is appropriate?","Refuse and complete each act and certificate properly","An employer cannot require the notary to pre-certify future unknown acts.",["Provide them because the employer paid for the seal","Payment does not control the notary's official judgment."],["Provide them only on Fridays","The day does not cure the problem."],["Leave the pages unsigned but lend the seal","Lending the device also compromises the notary's control."]],
["Why is signing a certificate before identifying the principal improper?","The notary would certify facts not yet established","Identity and the required act must be completed before the notary issues a truthful certificate.",["Because the notary must sell stationery first","Stationery sales are not a notarial prerequisite."],["Because identification is always optional","Identification is a required safeguard for signature acts."],["Only because the seal ink may dry","The issue is certification of unestablished facts."]],
["A customer says the notary can complete the ceremony after certifying it. What is the flaw?","A certificate cannot truthfully attest to an act that has not occurred","Notarial certification follows the actual required act; an intended later ceremony is not a completed one.",["Future intentions count as completed acts","An intention does not establish occurrence."],["The customer may certify the notary's future conduct","The customer does not make the notary's official certification."],["A larger bond permits advance certification","Bond amount does not authorize false certificates."]],
]},
{card:31,study:"certificates",topic:"acknowledgments",source:GUIDE+"; Making Corrections",items:[
["A notary discovers a certificate entry is wrong before handing the document back. What should be done?","Correct the certificate accurately rather than leave a known error","The guide addresses certificate corrections; the completed certificate must accurately describe the act actually performed.",["Ignore the error because the seal is clear","A legible seal does not cure incorrect certificate facts."],["Change the underlying contract without authority","The notarial certificate is distinct from the parties' substantive contract."],["Cover the entire record with the seal","An oversized impression does not correct facts."]],
["A certificate's venue mistakenly names the notary's home county instead of the county of the act. What needs correction?","The actual county of the act","The certificate's venue describes the notarial act's location; it is not automatically the notary's county of residence.",["The signer's residence instead","The signer's home is not the act's venue."],["The bond amount","A bond correction does not fix the venue."],["The document's filing state","The eventual filing place does not establish the act's location."]],
["A customer asks to change a completed certificate from acknowledgment to jurat without a sworn act. What is required?","Perform the required jurat first","A correction cannot invent an oath or execution that never occurred.",["Simply replace the heading","Changing words cannot create the missing act."],["Have a courier add sworn language","A courier cannot supply the absent affiant's sworn act."],["Charge a correction fee and skip the oath","Payment does not replace required conduct."]],
["May a notary use a correction to make a previously accurate date fit a customer's preferred deadline?","No, retain the truthful date","Correcting a genuine error differs from intentionally inserting a false date to satisfy a deadline.",["Yes; any customer request is a factual correction","A preference is not proof the original fact was wrong."],["Yes; if a lender asks","A lender cannot authorize false certification."],["Yes; after changing the seal's date by hand","Altering seal information does not justify a false act date."]],
]},
{card:32,study:"certificates",topic:"seals-fees",source:GUIDE+"; Notary Seal",items:[
["A seal impression contains outdated commission information. What should the notary avoid?","Hand-altering the seal impression to make it appear current","The guide warns against altering a seal impression; the notary should obtain and use a proper current device.",["Obtaining a correct seal","A correct device addresses the underlying problem."],["Checking the commission information","Checking information is appropriate."],["Keeping the device under personal control","Personal control is an ongoing safeguard."]],
["May the notary cross out the expiration date within an old seal impression and write a new one to update it?","No; do not alter the seal impression","A handwritten change to an outdated impression is not the proper way to create a current official seal.",["Yes; any new handwritten date works","That improperly alters the official impression."],["Yes; if the signer initials it","Signer initials do not update the notary's seal."],["Yes; because expiration dates are optional","Expiration information is part of Indiana's required seal contents."]],
["A notary's device has the wrong commission number. What addresses the actual defect?","Obtain a device bearing the correct commission information","A device should produce the required accurate information; repeatedly patching erroneous impressions does not correct the device.",["Tell every customer to overwrite the number","Customers should not alter the official impression."],["Use the incorrect number until the ink runs out","Known incorrect information should not be used."],["Remove the commission number from every impression","The required number cannot simply be omitted."]],
["Why is fixing a certificate typo different from editing the stamped official seal?","The seal impression must itself represent the proper official device information","Certificate corrections do not authorize manual alteration of the official seal impression.",["Because certificate facts never matter","Certificate accuracy remains essential."],["Because any alteration becomes lawful if initialed","Initialing does not create blanket permission to alter seals."],["Because the customer owns the seal information","Official commission information is not chosen by the customer."]],
]},
{card:33,study:"certificates",topic:"prohibited-acts",source:SOS+"; Certificate Selection",items:[
["Who chooses the type of notarial certificate when legal judgment about the transaction is needed?","The customer or a qualified legal adviser","The SOS presentation instructs notaries not to advise which certificate is legally best and to let the customer choose.",["The notary, based on which certificate is easiest to complete","Ease of completion does not authorize the notary to make the legal choice."],["The notary, based on the amount the customer agrees to pay","Payment does not authorize legal advice about which act is appropriate."],["The notary, by using the same act for every transaction","Transactions can require different acts. A fixed default does not supply the customer's legal instructions."]],
["A signer asks whether an acknowledgment or jurat will best protect ownership rights. What is appropriate for a nonattorney notary?","Refer the legal-choice question","The question asks about legal consequences; the notary should not select the act by giving unauthorized legal advice.",["Guarantee that a jurat wins all disputes","No notarial act guarantees that outcome."],["Choose acknowledgment because its name is shorter","Convenience is not a legal basis."],["Rewrite the ownership terms","Drafting transaction rights exceeds ordinary notarial functions."]],
["May a notary neutrally explain that a jurat includes an oath while an acknowledgment concerns acknowledged execution?","Yes, explain procedures without legal advice","Describing notarial procedures helps the customer obtain instructions while avoiding advice on which act is legally best.",["No; even stating an act's procedure is forbidden","The concern is unauthorized legal selection, not basic procedural explanation."],["Yes; and therefore choose every client's act","Procedural explanation does not authorize legal advice."],["Yes; and guarantee the receiving agency will accept it","An explanation does not guarantee acceptance."]],
["A document has no certificate and the signer cannot say what act is wanted. What should the notary do?","Have the signer obtain instructions","The notary should not invent legal instructions; the requested act must be established so its requirements can be performed.",["Pick a certificate at random","Random selection may perform the wrong act."],["Stamp the empty margin only","A stamp alone does not supply the required certificate."],["Select whichever certificate avoids identification","The acts still require appropriate safeguards."]],
]},
{card:34,study:"seals-records",topic:"seals-fees",source:SOS+"; Notary Seals",items:[
["Which words must appear on an Indiana notary seal?","Notary public and State of Indiana","The SOS seal checklist requires these words along with the commissioned name, commission number, and expiration information.",["Only Official Document","Generic wording does not supply the required office and state."],["Only the employer's trade name","A company name does not identify the notarial office."],["Only Certified True","Those words do not meet the required seal contents."]],
["How must the notary's name appear on the seal?","Exactly as it appears on the commission","The SOS presentation requires the exact commissioned name, not a preferred nickname or the employer's name.",["In any nickname the customer recognizes","A nickname does not satisfy the exact-name rule."],["As the employer's name only","The commission belongs to the individual."],["As the customer's name","The seal identifies the notary, not the principal."]],
["Which commission-number wording does the SOS seal checklist require?","Commission number and its identifying words","The seal must state the required number with its identifying wording, in addition to the other mandated information.",["The last four digits of the customer's ID","A customer's ID number is not the notary commission number."],["The office telephone number only","A telephone number cannot replace the commission number."],["The bond agent's account number","A bond account is not the notary's commission number."]],
["What expiration information is required on the seal?","Commission expiration and its identifying words","The required seal information includes the commission's actual expiration date and the identifying words.",["Only the date the stamp was shipped","Shipping date is unrelated to commission expiration."],["Only the customer's deadline","A transaction deadline is not commission information."],["No expiration if the notary has insurance","Insurance does not waive the seal requirement."]],
]},
{card:35,study:"seals-records",topic:"seals-fees",source:GUIDE+"; Notary Seal; "+LAW+"; IC 33-42-10-1",items:[
["Why must an official seal impression be legible and reproducible?","Its required information must remain readable when the record is copied","Indiana's stamping requirements include an impression capable of photographic reproduction with the record.",["So the notary can avoid signing","A reproducible seal does not replace a signature."],["So all document contents become true","Reproducibility has no truth-guarantee effect."],["So the customer can reuse it on another record","The impression belongs to the particular notarized record."]],
["A seal lands partly off the page and required information is missing. What is the problem?","The impression does not legibly show all required seal information","The notary must produce a proper readable impression rather than rely on a partial stamp.",["Nothing if the office is busy","Workload does not excuse missing seal information."],["Only the paper color is wrong","The stated defect is the incomplete impression."],["It becomes valid if the customer guesses the missing number","A guess does not supply the official seal information."]],
["Where should a notary avoid placing a seal impression?","Across text or signatures so that essential information is obscured","The seal and certificate need to remain readable without making the underlying record illegible.",["Anywhere the required information remains clear","Clear placement is the goal, not a defect."],["In a suitable open area near the certificate","A suitable clear area supports proper completion."],["On the record associated with the certificate","Association with the actual record is necessary."]],
["Does an ornate seal design excuse unreadable required information?","No; readability of the required information still matters","Optional design elements cannot displace or obscure the mandated office, state, name, number, and expiration information.",["Yes; decoration replaces required words","Decoration cannot substitute for the checklist."],["Yes; if the customer likes it","Customer preference does not waive legal requirements."],["Yes; because a seal never needs to be copied","Reproducibility is part of the stamping standard."]],
]},
{card:36,study:"seals-records",topic:"seals-fees",source:GUIDE+"; Notary Seal; "+LAW+"; IC 33-42-10-3",items:[
["Who must maintain control of the notary's stamping device?","The commissioned notary","The stamping device is personal to the notary and must remain under the notary's control to prevent unauthorized use.",["Every employee in the office","Shared access invites use by uncommissioned persons."],["Any customer who pays the fee","Paying for an act does not confer control of the device."],["The employer alone because it paid","Payment does not transfer the notary's official authority."]],
["An employer buys the seal and wants to keep it in a drawer accessible to all staff. What should the notary insist on?","Personal control that prevents unauthorized use","The device's purchaser cannot override the commissioned notary's responsibility for its security and use.",["Unlimited staff access","Other staff cannot use the personal commission."],["A rule allowing stamping when the notary is absent","The notary's absence does not delegate authority."],["Customer permission for each coworker","A customer cannot commission the coworker."]],
["May a notary lend a personal seal to a trusted uncommissioned coworker?","No, the coworker cannot use it","The notary must prevent another person from exercising the commission through the device.",["Yes; trust is equivalent to appointment","Personal trust is not a public commission."],["Yes; for fewer than ten records","The number of unauthorized acts does not authorize them."],["Yes; if no fee is charged","A free act still requires an authorized officer."]],
["What is a practical reason to secure the stamping device when leaving the desk?","To prevent unauthorized seal use","Securing the device supports the notary's duty of control and reduces the risk of fabricated certifications.",["To transfer the commission to the building","Storage does not transfer public office."],["To make identification optional later","Device security does not eliminate signer identification."],["To replace the need for certificates","A secure stamp still must accompany proper certification."]],
]},
{card:37,study:"seals-records",topic:"seals-fees",source:GUIDE+"; Lost or Stolen Seal; "+LAW+"; IC 33-42-10-3",items:[
["What should a notary do after discovering the stamping device has been stolen?","Promptly notify the Secretary of State","Indiana's device-control provisions require prompt notice of a lost or stolen stamping device.",["Wait until the eight-year term ends","Waiting leaves the office uninformed of a compromised device."],["Tell only the next customer","Customer notice is not notice to the commissioning office."],["Keep using another person's seal","Another notary's seal is not a substitute for the personal device."]],
["A notary cannot find the seal after an office move. Is it safe to ignore the loss because no misuse is known?","No; notify the Secretary of State promptly","The notice duty applies to a lost device, without requiring proof that misuse has already occurred.",["Yes; only proven fraud needs reporting","The statutory safeguard includes loss itself."],["Yes; if the employer promises to look someday","A vague search promise does not replace prompt notice."],["Yes; because the commission number is public","Public commission information does not make a missing device harmless."]],
["What distinguishes buying a replacement stamp from reporting a lost one?","A replacement does not itself give the Secretary of State notice of the loss","The notary should address both the missing device and the required official notification; purchasing equipment alone is not reporting.",["They are always the same transaction","A retailer's order is not automatically the required notice."],["A replacement erases all old impressions","A new stamp cannot erase prior or fraudulent impressions."],["A replacement automatically issues a new commission","Buying a device does not grant a commission."]],
["Why should the report of a stolen seal be prompt?","The compromised device may be used without the notary's authority","Prompt notice alerts the responsible office while the notary addresses a device that is no longer under personal control.",["It lets the thief lawfully notarize","The thief never gains authority through possession."],["It extends the commission by eight years","Reporting does not extend the term."],["It waives all past notarial errors","Notice does not create blanket immunity."]],
]},
{card:38,study:"seals-records",topic:"seals-fees",source:GUIDE+"; Seal at End of Commission; "+LAW+"; IC 33-42-10-3",items:[
["What does the Indiana guide say to do with the seal when a notary discontinues service?","Destroy or disfigure it to prevent fraudulent use","The official guide directs that a discontinued notary's seal should be destroyed or disfigured to prevent fraudulent use.",["Give it to a new uncommissioned employee","A used device does not confer authority on a successor."],["Leave it available for future customers","Future access risks unauthorized use."],["Sell it as a ready-to-use current commission","A device cannot transfer or revive the ended commission."]],
["Does an expired physical stamp allow the former notary to keep performing acts?","No, the commission has expired","The commission's validity controls authority; an old device cannot extend the term.",["Yes; until the ink runs out","Ink supply has no bearing on the commission's expiration."],["Yes; if the notary has many years of experience","Experience does not extend official authority."],["Yes; when the customer asks politely","Customer preference cannot revive an ended commission."]],
["If a notary dies, who may have responsibility under the device rule to prevent further use?","The appropriate personal representative or person in possession under the statute","The device-control provision addresses death and incapacity so the device cannot continue to be used after personal authority ends.",["Any customer who wants a free stamp","Customers do not inherit the commission."],["The first person to print a certificate","Printing does not create representative authority."],["Nobody; death transfers the office to the employer","The commission is personal and is not inherited by the employer."]],
["Must destruction always be the only possible way to prevent further use of a former notary's device?","No; the statute lists several methods that preclude further use","The rule's objective is preventing further impressions; its listed methods include securing or erasing as well as destruction.",["Yes; all other listed methods are forbidden","The statutory alternatives are not limited to destruction."],["No; leaving it on a public counter is enough","Public availability does not preclude use."],["No; a warning label alone permits continued notarizing","A label does not extend authority or disable the device."]],
]},
{card:39,study:"seals-records",topic:"journals",source:GUIDE+"; Duties: Journal Recommendation",items:[
["How does the guide treat a journal for ordinary traditional notarizations?","It recommends keeping a record of notarial acts","The traditional-notary guide recommends a journal as a useful record; that recommendation should not be confused with a universal statutory paper-journal mandate.",["It forbids every traditional journal","The guide recommends recordkeeping rather than prohibiting it."],["It requires every traditional signer to supply a thumbprint","The journal recommendation does not create that universal requirement."],["It replaces the actual notarial certificate","A journal is not a substitute for the certificate on the record."]],
["Why can a properly maintained journal help a traditional notary?","It can document what act occurred and the evidence reviewed","A contemporaneous record can assist with later questions about the date, principal, act, identification, and other relevant details.",["It makes an absent signer personally appear","A record cannot supply missing personal appearance."],["It guarantees the notary can never be sued","Recordkeeping does not create immunity."],["It authorizes higher fees automatically","A journal does not increase statutory fee limits."]],
["Does writing a journal entry cure failure to administer a required oath?","No, the oath must actually occur","The journal should reflect the actual notarization, and cannot supply an oath or affirmation that never occurred.",["Yes; any entry is legally an oath","Writing a note is not administering an oath."],["Yes; if the entry has the customer's name","A name does not establish the missing act."],["Yes; if the journal is bound","Binding does not cure substantive omissions."]],
["Which statement avoids importing another state's journal rule into ordinary Indiana study?","Use Indiana's own journal guidance","State requirements differ; a rule from another jurisdiction should not be presented as Indiana's universal paper-journal law.",["Apply whichever state's journal rule seems most detailed","Another state's detailed rule does not establish Indiana's requirements."],["Treat a recommended journal as a substitute for a certificate","The certificate remains necessary even when the notary records the act."],["Assume all states impose the same paper-journal requirement","Notarial requirements vary by jurisdiction."]],
]},
{card:40,study:"seals-records",topic:"prohibited-acts",source:GUIDE+"; Liability; "+LAW+"; IC 33-42-12-1(g); "+SOS+"; Employees and Discipline",items:[
["Does holding an Indiana notary commission immunize the notary from consequences of misconduct?","No; the commission does not confer immunity","A commission authorizes proper acts but does not shield the notary from civil, criminal, or disciplinary consequences of improper conduct.",["Yes; all public officials have blanket immunity","The commission does not supply that blanket protection."],["Yes; a bond erases personal responsibility","A bond does not excuse misconduct."],["Yes; if the notary works for an attorney","Employment does not remove personal responsibility."]],
["A notary follows an employer's order to falsify a certificate. Who remains responsible for the notary's official conduct?","The notary remains personally responsible","The SOS presentation emphasizes independent judgment and personal responsibility despite employment; employer involvement does not excuse the notary.",["Only the customer can ever be responsible","The notary has independent official duties."],["Nobody because the employer ordered it","An order does not make misconduct consequence-free."],["Only the seal manufacturer","Manufacturing a device is not performing the act."]],
["Which consequence can the Secretary of State impose for notary misconduct?","Suspension or revocation of the commission","The SOS presentation lists denial, refusal, revocation, suspension, and conditions among the office's disciplinary powers.",["Automatic lifetime immunity","Discipline is the opposite of immunity."],["A guaranteed new commission without review","Misconduct does not guarantee a new commission."],["Transfer of the notary's authority to the customer","A customer does not acquire the office through a complaint."]],
["Does a notary's bond make careless notarizations acceptable because a surety may pay a claim?","No; the notary must still perform every act properly","Financial protection for injured members of the public does not waive the notary's legal duties or personal responsibility.",["Yes; bond coverage is permission to skip safeguards","Coverage is not authority to disregard requirements."],["Yes; if the potential loss is below $25,000","A smaller loss does not authorize misconduct."],["Yes; if the notary charges no fee","Unpaid acts still require proper performance."]],
]},
{card:41,study:"seals-records",topic:"acknowledgments",source:GUIDE+"; Secretary of State Apostilles and Authentications",items:[
["What does an apostille authenticate in relation to a notarized record?","The official signature, capacity, and seal","Authentication concerns the public official's signature or authority; it is not an approval of every substantive statement in the record.",["The factual accuracy of the notarized record's contents","Authentication of the official does not verify the underlying factual assertions."],["The legal enforceability of every term in the record","An apostille does not adjudicate the transaction's enforceability."],["The receiving country's approval of the transaction","An apostille does not guarantee the foreign recipient's decision."]],
["Does an ordinary notary's commission authorize the notary to issue the State's apostille?","No; State authentication is obtained from the appropriate public office","Performing a notarization and issuing a State apostille are separate functions.",["Yes; every notarial stamp is an apostille","The notarial seal and apostille are different instruments."],["Yes; if the document is in another language","Language does not confer authentication authority."],["Yes; after charging an additional ten dollars","A fee cannot create the State's apostille authority."]],
["A customer wants a record notarized for foreign use. Does the foreign destination itself move the Indiana act outside Indiana?","No; the act's venue remains where the Indiana notary performs it","The notary records the actual location and performs the appropriate act; any later authentication is a separate process.",["Yes; use the foreign country as the Indiana venue","Destination does not establish the act's location."],["Yes; the notary must pretend to be a foreign official","The notary must not misstate official capacity."],["No; therefore all foreign legal requirements are guaranteed","A proper Indiana act does not guarantee every foreign requirement."]],
["Why might an apostille request be refused when the notarial certificate is incomplete?","The State must be able to authenticate a properly evidenced official act","The SOS presentation notes rejection of improper notarizations in the apostille process; a seal alone does not fix a missing certificate.",["Because an apostille replaces missing notarization steps","Authentication cannot retroactively perform the missing act."],["Because foreign-use records never need signatures","Signature authentication presupposes a properly evidenced official signature."],["Because the customer may choose any notary number","Commission information must correspond to the official involved."]],
]},
{card:42,study:"seals-records",topic:"seals-fees",source:SOS+"; Notary Fees; "+GUIDE+"; Fees; "+LAW+"; IC 33-42-14-1",items:[
["What maximum ordinary notarial-act fee does the SOS presentation state?","$10 per notarial act","The Secretary of State states that an ordinary notary may charge up to ten dollars per notarial act.",["$25 for every ordinary act","Twenty-five dollars is not the ordinary-act ceiling stated here."],["$100 per signature without limits","That exceeds the stated ordinary-act maximum."],["Any amount demanded by the customer","Customer willingness does not remove the fee limit."]],
["Must a notary always charge the maximum permitted ordinary fee?","No; the stated amount is a maximum","Permission to charge up to a limit does not require charging that limit for every act.",["Yes; free service is always prohibited","A permitted maximum is not a mandatory minimum."],["Yes; the bond depends on charging ten dollars","The bond requirement does not depend on always charging the maximum."],["No; therefore any higher amount is allowed","Charging less does not eliminate the upper limit."]],
["A single ordinary act uses a three-page record. Does page count alone authorize three separate ten-dollar notarial charges?","No; the stated fee is per notarial act","The SOS presentation states the fee per act, not per page of the underlying record.",["Yes; every page is automatically a separate act","A page is not automatically a separate notarial act."],["Yes; photocopies always multiply the act fee","Copy count alone does not establish additional performed acts."],["No; the notary must instead charge one hundred dollars","There is no such mandatory charge in the stated rule."]],
["What fee practice should a notary follow before providing service?","Make the applicable charges clear and comply with the required fee display","The guide's fee rules address public notice; the SOS presentation also identifies improper fee information and overcharging as misconduct.",["Conceal charges until after the seal is applied","Surprise charges conflict with proper fee notice."],["Advertise ten dollars but demand a larger notarial fee later","A posted fee does not justify exceeding the limit."],["Let a customer's urgency set an unlimited act fee","Urgency does not waive the ordinary maximum."]],
["A notary performs two separate ordinary notarial acts. What is the combined maximum act fee at ten dollars per act?","$20, excluding any separately lawful travel charge","Two actually performed ordinary acts at the ten-dollar ceiling total twenty dollars; other charges must independently comply with applicable rules.",["$10 because all visits have a one-act limit","The stated limit is per act, not per visit."],["$30 because the meeting counts as a third act","A meeting is not automatically another notarial act."],["An unlimited amount because two acts are involved","Multiple acts do not remove the per-act limit."]],
]},
{card:43,study:"conflicts-refusal",topic:"prohibited-acts",source:GUIDE+"; Conflicts of Interest; "+LAW+"; IC 33-42-13-3",items:[
["May a notary notarize the notary's own signature?","No, use another notary","The guide's conflict rules prohibit self-notarization; the principal should use another qualified notary.",["Yes; if the notary knows their own identity","Identity certainty does not cure self-interest."],["Yes; with a second seal impression","More impressions do not remove the conflict."],["Yes; if the act is free","A fee waiver does not make self-notarization proper."]],
["A transaction directly benefits the notary's spouse. What should the notary do?","Refer it to another notary","Indiana's conflict provision addresses direct beneficial interests of the notary or spouse.",["Proceed because only the notary's benefit matters","The provision also covers a spouse's direct beneficial interest."],["Proceed if the spouse gives written consent","Consent does not remove the statutory conflict."],["Proceed using the employer's seal","A different device does not change the notary's conflict."]],
["Does an ordinary authorized notarial fee itself mean every paid act is prohibited as a direct-benefit conflict?","No, an authorized act fee is permitted","The conflict rule should not be read to prohibit the ordinary permitted fee for performing the act.",["Yes; all fee-charging notaries are automatically conflicted","That would contradict the ordinary statutory fee permission."],["No; therefore every financial interest is allowed","An allowed fee does not excuse a direct transaction benefit."],["Yes; unless the fee is concealed","Concealment does not resolve conflicts or fee duties."]],
["A notary has a direct financial stake in the deal and the parties want that notary anyway. What is appropriate?","Refer the act to an impartial qualified notary","The parties' preference does not eliminate the notary's prohibited direct-benefit conflict.",["Proceed because all parties consent","Consent does not waive the statutory restriction."],["Proceed but omit the notary's name","Omitting required information compounds the problem."],["Proceed if a journal entry mentions the stake","Recording a conflict does not authorize the act."]],
]},
{card:44,study:"conflicts-refusal",topic:"prohibited-acts",source:SOS+"; Employees as Notaries",items:[
["Does a supervisor's instruction override a notary's independent official judgment?","No, the notary exercises independent judgment","The SOS presentation stresses that an employee notary remains personally responsible for the commission and acts.",["Yes; employment contracts replace notarial law","A private arrangement does not displace public duties."],["Yes; if the supervisor paid the application fee","Payment does not transfer official judgment."],["Yes; whenever a client complains","A complaint does not authorize improper notarization."]],
["An attorney-employer asks an employee notary to ignore a missing signer. What should the notary do?","Decline to perform an act lacking the required personal appearance","An employer's professional title does not remove the notary's independent responsibility to meet the act's requirements.",["Comply because all attorney instructions are binding","The notary remains responsible for legal notarial performance."],["Let the attorney use the employee's seal","Lending the device does not cure missing appearance."],["Certify the act and ask questions afterward","Required facts must be established before certification."]],
["Can an employer be exposed to liability for an employee notary's misconduct?","Yes, employer liability is possible","Potential employer liability exists alongside the notary's personal responsibilities and does not replace them.",["No; employers can never be liable","The presentation expressly warns otherwise."],["Yes; therefore the employee has no responsibility","Employer exposure does not eliminate the notary's duties."],["Only the customer can ever face consequences","Consequences are not restricted to the customer."]],
["A notary leaves employment. Does the former employer acquire the individual's commission by having paid its costs?","No; the commission remains personal to the commissioned individual","The notarial office is held by the individual; payment of fees or equipment costs does not make it a company-owned commission.",["Yes; every purchased commission becomes company property","A public commission is not transferred by payment."],["Yes; the successor employee may immediately use the same name","A successor cannot impersonate the commissioned notary."],["No; the former employer may still sign certificates in that name","Signing in the notary's name is not authorized."]],
]},
{card:45,study:"conflicts-refusal",topic:"prohibited-acts",source:GUIDE+"; Blank Documents and Incomplete Certificates",items:[
["A customer offers a record with material transaction blanks to be filled after notarization. What should the notary do?","Have the record properly completed before proceeding","The guide warns against blank or incomplete records because later additions can change what the principal executed.",["Let the customer fill any terms after certification","Later substantive additions create an incomplete-record risk."],["Fill in legal terms based on the notary's guess","The notary should not invent the parties' legal terms."],["Charge more for blank spaces","A higher fee does not cure incompleteness."]],
["Why are unfilled material blanks in a notarized record a concern?","Terms could be added after execution","The guide's blank-record warning protects against treating an unfinished record as a completed act.",["They automatically turn the record into a birth certificate","Blank spaces do not change the record's type that way."],["They remove the need for identification","Incomplete text does not waive identity requirements."],["They allow the notary to write any deal they prefer","The notary does not choose substantive contract terms."]],
["May a notary give a customer a signed and sealed certificate with the principal's name blank?","No, identify the actual principal","Leaving essential certificate facts for someone else to invent permits misuse and does not evidence a properly completed act.",["Yes; a customer can select the principal later","The certificate must correspond to the actual act and person."],["Yes; if the date is filled","One completed field does not cure an essential blank."],["Yes; if the seal is legible","Legibility does not cure incomplete certificate facts."]],
["Who should supply missing substantive transaction terms before notarization?","The parties or their authorized adviser","The record must be completed appropriately without the notary providing unauthorized drafting or legal advice.",["The notary, using the most common contract terms","Common wording does not authorize the notary to choose the parties' legal terms."],["The notary, using a previous customer's completed record","A previous transaction does not supply authority to draft this customer's terms."],["The notary, after the parties agree to an extra fee","A drafting fee does not grant legal authority beyond the commission."]],
]},
{card:46,study:"conflicts-refusal",topic:"prohibited-acts",source:GUIDE+"; Duties and Refusal; "+LAW+"; IC 33-42-9-5",items:[
["The notary is not satisfied the signer is acting knowingly and voluntarily. What may the notary do?","Refuse the act","Indiana allows refusal when the notarial officer is not satisfied as to competence or knowing and voluntary execution.",["Ignore the concern if the fee is paid","Payment does not cure a willingness concern."],["Ask the employer to guess the signer's wishes","The notary must exercise independent judgment."],["Backdate the certificate to before the concern arose","False dating does not resolve the issue."]],
["A companion threatens the signer to obtain a signature. What is the appropriate response?","Stop while voluntariness is unresolved","Coercion undermines the knowing and voluntary execution the notary must evaluate.",["Proceed because the companion is confident","The companion's confidence is not the signer's free choice."],["Proceed if the companion signs the receipt","A receipt does not remove coercion."],["Use a copy certificate instead","Changing the act does not justify concealing coercion."]],
["A signer appears unable to understand what is happening and cannot communicate a knowing choice. What may the notary do?","Decline with competence unresolved","The refusal provision permits the notary to stop when not satisfied as to competence or voluntary knowing action.",["Automatically appoint themself guardian","A notary commission does not confer guardianship authority."],["Let any visitor decide instead","A visitor's preference does not establish the principal's capacity."],["Proceed because the paper is already printed","Printed paper does not establish competence."]],
["Is the notary's discretion to refuse unlimited, including refusals prohibited by other law?","No; refusal remains subject to legal prohibitions","Indiana's refusal authority includes a boundary: a refusal cannot be one that law prohibits.",["Yes; public duties never constrain refusal","The statute expressly recognizes a legal boundary."],["Yes; a journal note makes every refusal lawful","A note cannot authorize unlawful discrimination or another prohibited refusal."],["No; therefore every requested act must be done even if illegal","Legal limits on refusal do not require performing improper acts."]],
["A deadline is minutes away, but the signer says they do not want to sign. What should the notary do?","Respect the lack of voluntary execution and do not notarize it","Time pressure does not supply consent; the notary must not certify a voluntary act when the signer refuses it.",["Let the deadline substitute for consent","Urgency is not the signer's voluntary choice."],["Have the requester force the signature","Coercion makes the voluntariness problem worse."],["Certify an acknowledgment without asking the signer","The acknowledgment must actually be received from the principal."]],
]},
{card:47,study:"conflicts-refusal",topic:"acknowledgments",source:GUIDE+"; Blind Signers; "+LAW+"; IC 33-42-13-3(a)(6)",items:[
["Before taking a blind person's acknowledgment, what safeguard does Indiana's provision require?","Read the record to the person before acknowledging the signature","The provision addresses reading the record so the person is informed of its contents before the acknowledgment.",["Refuse every blind signer automatically","Blindness alone does not justify an automatic prohibition."],["Assume any companion has already read it","The notary must address the specified safeguard rather than assume it."],["Replace the record with a blank certificate","That does not inform the principal about the record."]],
["Does blindness alone mean a person cannot knowingly acknowledge a signature?","No, meet the safeguard and assess the act","The rule supplies a reading safeguard rather than treating blindness as automatic incapacity.",["Yes; all blind signers lack legal capacity","Disability is not itself proof of incapacity."],["Yes; only a relative can act as the notary","The rule does not create that relative-only requirement."],["No; therefore skip the required reading","Accommodation does not remove the specific safeguard."]],
["A blind signer says a courier summarized the record. What should the notary avoid?","Relying on the summary instead of reading","The acknowledgment safeguard must be met rather than assumed from a courier's account.",["Making the record accessible through the required reading","Reading is the specified safeguard."],["Identifying the signer properly","Identification remains necessary."],["Checking that the act is voluntary","Willingness remains relevant."]],
["Does reading a record for a blind principal authorize the notary to decide whether the deal is legally favorable?","No; reading is an accessibility safeguard, not legal advice","The notary can meet the reading requirement without advising on the legal merits of the transaction.",["Yes; reading creates an attorney-client relationship automatically","A notary's reading does not confer a law license."],["Yes; the notary must choose every contract term","Ordinary notarization does not authorize substantive drafting."],["No; therefore the notary may refuse to read it","The lack of legal-advice authority does not eliminate the safeguard."]],
]},
{card:48,study:"conflicts-refusal",topic:"acknowledgments",source:GUIDE+"; Foreign Languages; "+LAW+"; IC 33-42-13-3(a)(7)",items:[
["What safeguard applies to an acknowledgment by a person who does not speak or understand English?","Translate the record's nature and effect","Indiana's provision addresses understanding the nature and effect of the record before acknowledgment.",["Use a louder English voice only","Volume does not translate meaning."],["Assume a signature proves understanding of all terms","A signature alone does not establish the specified translation."],["Certify that the notary wrote the translation when that is false","The certificate must not falsely describe the notary's acts."]],
["A signer cannot understand the language used to explain the transaction. What should the notary avoid?","Proceeding on an unsupported assumption of understanding","The notary must address communication and the applicable translation safeguard rather than infer understanding from a nod alone.",["Ensuring the person understands the nature and effect","Understanding is the point of the safeguard."],["Pausing to obtain appropriate language assistance","A pause can help meet the requirement."],["Using accurate certificate facts","Accurate certification remains essential."]],
["Does notarizing a signature automatically certify the accuracy of every translation attached to the record?","No; the certificate must be limited to the actual notarial act","A signature notarization does not by itself make the notary a translator or guarantor of translated contents.",["Yes; every seal certifies all translations","A seal does not expand the act's scope that way."],["Yes; even if the notary cannot read either language","Lack of language knowledge cannot support a translation guarantee."],["No; therefore communication with the signer never matters","Communication and understanding remain necessary safeguards."]],
["A foreign-language record is presented to a notary. Which question is most relevant before proceeding?","Can the safeguards be satisfied?","Document language does not justify inventing facts; the notary must ensure proper communication, the applicable translation safeguard, and truthful certification.",["Does a signature alone prove the signer understands the record?","The applicable understanding and translation safeguards still need to be satisfied."],["Can an English certificate replace communication with the signer?","Certificate language does not by itself establish the signer's understanding."],["Will a translated heading alone establish the record's nature and effect?","Translating only a heading does not necessarily communicate the record's nature and effect."]],
]},
{card:49,study:"conflicts-refusal",topic:"prohibited-acts",source:GUIDE+"; Fraudulent Advertising and Notario Publico; "+LAW+"; IC 33-42-13-3",items:[
["An Indiana notary who is not an attorney plans a Spanish-language flyer headed \"Notario Publico.\" What change is required?","Remove the prohibited title","Indiana prohibits a notary who is not licensed to practice law in Indiana from using notario or notario publico. A disclaimer does not authorize the title.",["Keep the title and add a nonattorney disclaimer","The advertising disclaimer does not create an exception to the prohibited title for a nonattorney."],["Use the title only when the service is free","Providing free service does not grant a nonattorney permission to use the title."],["Use the title after passing the notary exam","Passing the notary exam does not confer an Indiana law license or the title's attorney exception."]],
["A nonattorney notary offers to advise which legal rights a client should waive. What is the problem?","The commission grants no law license","Ordinary notarial authority concerns specified acts, not personalized legal advice about a client's rights.",["No problem if a seal is used","A seal does not authorize legal practice."],["No problem if the advice is called notarization","Relabeling advice does not change its nature."],["Only the paper size matters","The issue is unauthorized legal advice, not formatting."]],
["Why should advertising accurately describe the notary's qualifications?","To avoid implying attorney qualifications","The guide's advertising warnings address misleading claims of legal authority and professional status.",["A commission automatically grants every professional license","Notarial appointment is a limited public office."],["Advertising law applies only to paid websites","The medium does not create a general exemption."],["A disclaimer makes every prohibited claim permissible","A disclaimer is not blanket permission for false or prohibited representations."]],
["A customer asks a notary to prepare a deed and select legal ownership terms because the notary passed an exam. What is appropriate for a nonattorney?","Refer legal drafting and ownership advice to an appropriate professional","Passing a notary exam does not authorize a nonattorney to draft legal terms or give advice beyond notarial authority.",["Draft any terms because the exam grants a law license","The exam does not confer attorney status."],["Use the most expensive certificate as legal advice","Certificate fees do not determine ownership rights."],["Promise the deed cannot be challenged","The notary cannot guarantee that legal outcome."]],
]},
{card:50,study:"conflicts-refusal",topic:"prohibited-acts",source:GUIDE+"; Immigration and Original Records; "+LAW+"; IC 33-42-13-3",items:[
["Does an ordinary notary commission authorize providing paid immigration legal advice?","No, the commission grants no such authority","The guide warns against prohibited immigration assistance and misleading legal-service claims by nonattorney notaries.",["Yes; passing the notary exam qualifies an immigration lawyer","A notary exam is not a law license."],["Yes; if the client is a personal friend","Friendship does not confer immigration-law authority."],["Yes; if the notary uses a translated professional title","Translation does not create legal qualifications."]],
["May a notary keep a customer's original record merely to pressure the customer into buying more services?","No; the statute restricts withholding original records except where law permits","Original-record custody must not be used as leverage for additional services contrary to the statutory restriction.",["Yes; the seal makes the notary the record's owner","Notarization does not transfer ownership."],["Yes; if the notary's employer wants future business","A sales goal does not authorize withholding."],["Yes; whenever the customer is an immigrant","Immigration status does not create a withholding exception."]],
["A customer asks which immigration form to file and wants advice from the notary because the notarization is inexpensive. What should a nonqualified notary do?","Refer the immigration legal questions","A notary fee does not authorize immigration legal advice or selection of legal strategies.",["Choose a form at random","Guessing a legal form is not an authorized notarial function."],["Promise approval if a seal is added","A seal does not guarantee an immigration decision."],["Keep the passport until the client follows the advice","Withholding originals is not a proper way to compel acceptance."]],
["Does notarizing a customer's immigration-related affidavit guarantee the agency will approve the application?","No; it certifies the actual notarial act rather than the agency's decision","A proper notarization does not promise the truth of every claim or a favorable immigration outcome.",["Yes; a notarial seal binds the agency to approve","The agency is not bound to approve by a notarization."],["Yes; if the notary charges the maximum","A fee does not control agency adjudication."],["No; therefore an oath required for the affidavit may be skipped","The absence of a guarantee does not waive the requested act's requirements."]],
]},
];
